// Chlapské krabičky (TeloZdravo) – 100 receptov
window.DB_CK = [
{id:"ck1",n:"Praženica s fazuľou a šunkou",c:"ranajky",p:8,s:2,k:610,pr:45,ca:40,f:30,tm:15,
ing:["6 vajec","200 g bielej fazule (z konzervy, prepláchnutej)","100 g kvalitnej šunky (alebo chudej slaniny)","50 g tvrdého syra (čedar alebo eidam)","2 plátky kváskového chleba","1 ČL masla","soľ, hrubozrnné čierne korenie"],
st:["Na panvici rozohrej maslo a opeč na kocky nakrájanú šunku dozlatista.","Pridaj prepláchnutú fazuľu, premiešaj a nechaj minútu prehriať.","Vylej rozšľahané vajcia, osoľ, poriadne okoreň a miešaj do požadovanej hustoty.","Odstav z ohňa, posyp nastrúhaným syrom a zabaľ do krabičiek spolu s chlebom."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck2",n:"Tvarohové lievance s ovocím",c:"ranajky",p:9,s:2,k:470,pr:49,ca:32,f:15,tm:25,
ing:["250 g polotučného tvarohu","2 vajcia","60 g ovsených vločiek (rozmixovaných na múku)","2 odmerky proteínu (cca 60 g, ideálne vanilka)","100 g mrazeného lesného ovocia","1 ČL kokosového oleja (5 g na opekanie)","štipka škorice"],
st:["V miske poriadne zmiešaj tvaroh, vajcia, rozmixované vločky, proteín a škoricu na husté cesto.","Na panvici rozohrej kokosový olej na strednom ohni.","Lyžicou tvaruj na panvici lievance a opekaj ich z každej strany zhruba 2 minúty dozlatista.","Rozdeľ do krabičiek a navrch pridaj ovocie."],t:["mealprep","mikrovlnka"]},
{id:"ck3",n:"Raňajkový wrap so slaninou a vajíčkom",c:"ranajky",p:10,s:2,k:620,pr:38,ca:36,f:35,tm:15,
ing:["2 veľké celozrnné tortilly","5 vajec","50 g oravskej slaniny (na plátky)","100 g chudej šunky","40 g čedaru (nastrúhaného)","1 hrsť čerstvého špenátu","soľ, korenie"],
st:["Slaninu opeč na suchej panvici dochrumkava a daj ju bokom.","Na výpeku zo slaniny urob rýchlu praženicu z 5 vajec a nakrájanej šunky.","Tortillu zľahka nahrej, do stredu daj praženicu, slaninu, čerstvý špenát a posyp syrom.","Pevne zabaľ do wrapu. Pre lepšiu chuť môžeš wrap ešte minútu opiecť na panvici."],t:["mealprep","rychle"]},
{id:"ck4",n:"Zapekané vajcia s mozzarellou a šunkou",c:"ranajky",p:11,s:2,k:530,pr:45,ca:8,f:35,tm:25,
ing:["6 vajec","150 g kvalitnej šunky od kosti","100 g mozzarelly (nastrúhanej)","200 g lúpaných paradajok z konzervy","1 strúčik cesnaku","1 PL olivového oleja","oregano, soľ, korenie"],
st:["Na oleji krátko orestuj pretlačený cesnak a na kocky nakrájanú šunku.","Zalej lúpanými paradajkami, pridaj oregano, soľ, korenie a nechaj 5 minút prebublať.","Zmes rozdeľ do dvoch zapekacích misiek (alebo sklenených krabičiek vhodných do rúry).","Do každej misky rozbi 3 vajcia, posyp mozzarellou a daj zapiecť na 15 minút pri 200 °C."],t:["mealprep","mikrovlnka"]},
{id:"ck5",n:"Ovsená kaša s proteínom a arašidovým maslom",c:"ranajky",p:12,s:2,k:505,pr:40,ca:54,f:14,tm:10,
ing:["100 g ovsených vločiek","2 odmerky čokoládového proteínu (cca 60 g)","300 ml polotučného mlieka (alebo vody)","30 g 100% arašidového masla","1 stredný banán","štipka soli"],
st:["V hrnci zohrej mlieko, pridaj vločky a štipku soli. Var na miernom ohni 3–5 minút do zhustnutia.","Odstav z ohňa a vmiešaj proteínový prášok (ak je kaša príliš hustá, pridaj trochu vody).","Rozdeľ kašu do dvoch krabičiek.","Navrch každej porcie daj lyžicu arašidového masla a polovicu nakrájaného banánu."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck6",n:"Špenátová omeleta s mozzarellou a šunkou",c:"ranajky",p:13,s:2,k:570,pr:46,ca:9,f:39,tm:15,
ing:["8 vajec","100 g kuracej šunky","2 hrste čerstvého baby špenátu","100 g mozzarelly","50 g sušených paradajok (odkvapkaných z oleja)","1 PL masla (10 g)","soľ, čierne korenie"],
st:["Vajcia rozbi do misky, pridaj soľ, korenie a poriadne rozšľahaj vidličkou.","Na panvici roztop maslo, pridaj špenát, nakrájanú šunku a sušené paradajky. Restuj 1 minútu.","Zalej to rozšľahanými vajcami. Keď spodok omelety stuhne, posyp vrch syrom.","Omeletu prelož napoly, nechaj syr roztopiť a hotovú ju rozkroj na dve porcie."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck7",n:"Tuniaková nátierka s vajíčkom",c:"ranajky",p:14,s:2,k:545,pr:52,ca:52,f:14,tm:18,
ing:["2 konzervy tuniaka vo vlastnej šťave (čistá váha mäsa 260 g)","4 vajcia","50 g gréckeho jogurtu (alebo cottage cheese)","1 PL plnotučnej horčice","1 menšia červená cibuľa","4 krajce kváskového chleba (cca 200 g)","soľ, korenie, citrónová šťava"],
st:["Vajcia uvar natvrdo (8 minút), schlaď v studenej vode, ošúp a nakrájaj na malé kocky.","V miske zmiešaj odkvapkaného tuniaka, grécky jogurt, horčicu a nadrobno nasekanú cibuľu.","Pridaj nakrájané vajíčka, dochuť soľou, korením a pár kvapkami citrónu. Poriadne premiešaj.","Nátierku zbaľ do krabičky oddelene od chleba, aby sa nerozmočil."],t:["mealprep","rychle","studene"]},
{id:"ck8",n:"Sendvič s volským okom a slaninou",c:"ranajky",p:15,s:2,k:710,pr:36,ca:56,f:38,tm:15,
ing:["4 plátky hrubšieho kváskového chleba (cca 200 g)","4 vajcia","80 g chudej slaniny (plátky)","100 g chudej kuracej šunky","1/2 zrelého avokáda (cca 60 g)","60 g krémového syra (typu Lučina)","soľ, čierne korenie"],
st:["Plátky slaniny opeč na suchej panvici dochrumkava a odlož bokom.","Na výpeku zo slaniny urob 4 volské oká. Žĺtok nechaj mierne tekutý.","Plátky chleba natri krémovým syrom, ulož na ne roztlačené avokádo, šunku, slaninu a volské oká.","Prikry druhým plátkom chleba, zľahka pritlač a prekroj napoly pre ľahšie jedenie."],t:["rychle","studene"]},
{id:"ck9",n:"Shakshuka s klobásou a vajcami",c:"ranajky",p:16,s:2,k:560,pr:31,ca:40,f:30,tm:20,
ing:["4 vajcia","100 g klobásy chorizo (alebo inej pikantnejšej)","1 plechovka (400 g) lúpaných paradajok","1 červená paprika a 1 cibuľa","2 strúčiky cesnaku","2 krajce chleba (cca 100 g) na namáčanie","rímska rasca, údená paprika, soľ"],
st:["Na panvici orestuj na kolieska nakrájanú klobásu. Pridaj nakrájanú cibuľu, cesnak a papriku. Restuj 5 minút.","Zasyp koreninami, zalej lúpanými paradajkami a nechaj omáčku 5 minút zhustnúť.","Do omáčky urob lyžicou 4 jamky a do každej rozbi jedno vajce.","Prikry pokrievkou a dus 3–5 minút, kým bielka nestuhnú. Podávaj s chlebom."],t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"ck10",n:"Cottage cheese so šunkou a vajíčkom",c:"ranajky",p:17,s:2,k:545,pr:52,ca:36,f:21,tm:18,
ing:["400 g (2 tégliky) Cottage cheese","150 g kuracej šunky od kosti","4 vajcia","100 g cherry paradajok a 1 jarná cibuľka","2 plátky celozrnného chleba (cca 100 g)","soľ, čierne korenie"],
st:["Vajcia uvar natvrdo (8 minút), ošúp a nakrájaj na štvrtinky.","Vo veľkej miske zmiešaj Cottage cheese s na kocky nakrájanou šunkou a nasekanou jarnou cibuľkou.","Pridaj prekrojené cherry paradajky, osoľ, poriadne okoreň a premiešaj.","Zmes rozdeľ do krabičiek, navrch ulož uvarené vajcia a podávaj s opečeným chlebom."],t:["mealprep","rychle","studene"]},

{id:"ck11",n:"Kuracie prsia s ryžou a brokolicou",c:"obed",p:19,s:2,k:586,pr:56,ca:68,f:10,tm:25,
ing:["400 g kuracích pŕs","150 g ryže (v surovom stave)","300 g brokolice","1 PL olivového oleja","soľ, čierne korenie, mletá paprika"],
st:["Ryžu prepláchni a daj variť podľa návodu. Brokolicu rozober na ružičky a uvar v osolenej vode (cca 5 minút).","Kuracie prsia nakrájaj na plátky alebo kocky, osoľ a okoreň mletou paprikou.","Na panvici rozohrej olej a mäso sprudka opeč dozlatista (cca 8 minút).","Rozdeľ hotovú ryžu, mäso a brokolicu rovnomerne do dvoch krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck12",n:"Morčacie guľky s pečenými batatmi",c:"obed",p:20,s:2,k:560,pr:46,ca:40,f:24,tm:35,
ing:["400 g mletého morčacieho mäsa","400 g batatov (sladkých zemiakov)","1 vajce","1 PL olivového oleja","soľ, sušený cesnak, čierne korenie"],
st:["Rúru predhrej na 200 °C. Bataty ošúp, nakrájaj na kocky, pokvapkaj polovicou oleja, osoľ a daj na plech.","V miske rukami zmiešaj mleté mäso, vajce, soľ a cesnak. Vyformuj stredne veľké guľky.","Guľky poukladaj na plech k batatom (alebo na panvicu s druhou polovicou oleja).","Peč všetko spolu v rúre 25 minút, kým nie sú guľky prepečené a bataty mäkké."],t:["mealprep","mikrovlnka"]},
{id:"ck13",n:"Kuracie rezance s arašidovou omáčkou",c:"obed",p:21,s:2,k:501,pr:48,ca:57,f:9,tm:20,
ing:["350 g kuracích pŕs","120 g ryžových alebo soba rezancov (v surovom stave)","200 g mrazenej ázijskej zeleniny","30 g 100% arašidového masla","2 PL sójovej omáčky","soľ, čierne korenie"],
st:["Rezance zalej vriacou vodou a nechaj zmäknúť podľa návodu. Zlej vodu.","Kuracie prsia nakrájaj na tenké rezance a orestuj na suchej panvici dozlatista. Pridaj mrazenú zeleninu a dus 5 minút.","V malej miske rozmiešaj arašidové maslo, sójovú omáčku a trochu horúcej vody, aby vznikla tekutá omáčka.","Do panvice k mäsu pridaj rezance, zalej omáčkou, minútu poriadne premiešaj a zabaľ."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck14",n:"Morčacie kocky s kuskusom a fetou",c:"obed",p:22,s:2,k:570,pr:59,ca:52,f:14,tm:17,
ing:["400 g morčacích pŕs","120 g kuskusu (v surovom stave)","200 g cukety a červenej papriky","40 g syru Feta","1 PL olivového oleja","soľ, grilovacie korenie"],
st:["Kuskus nasyp do misky, mierne osoľ, zalej vriacou vodou (tesne nad okraj kuskusu) a prikry na 5 minút tanierom.","Morčacie mäso nakrájaj na kocky a posyp grilovacím korením.","Na panvici s olejom sprudka opeč mäso. Po 5 minútach pridaj nakrájanú zeleninu a restuj ďalších 5 minút do zmäknutia.","Do krabičiek naporcuj kuskus, pridaj mäso so zeleninou a navrch rozmrv syr Feta."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck15",n:"Kuracie prsia s hubovou omáčkou a ryžou",c:"obed",p:23,s:2,k:575,pr:56,ca:63,f:11,tm:25,
ing:["400 g kuracích pŕs","200 g čerstvých šampiňónov","100 ml smotany na varenie (12%)","150 g ryže (v surovom stave)","1 ČL masla (5 g)","soľ, mletá rasca"],
st:["Ryžu uvar vo vode podľa návodu. Kuracie prsia prekroj na tenšie plátky, osoľ a okoreň.","Na masle orestuj kuracie plátky z oboch strán dozlatista a vyber ich na tanier.","Do tej istej panvice daj nakrájané huby, osoľ a restuj, kým nepustia vodu a nezmäknú.","Zalej smotanou, nechaj minútu prebublať, vráť dnu mäso a rozdeľ do krabičiek spolu s ryžou."],t:["mealprep","mikrovlnka"]},
{id:"ck16",n:"Zapekané kuracie prsia s paradajkami",c:"obed",p:24,s:2,k:507,pr:63,ca:39,f:11,tm:35,
ing:["400 g kuracích pŕs","100 g mozzarelly (na plátky)","200 g cherry paradajok","400 g zemiakov","soľ, bazalka, čierne korenie"],
st:["Rúru predhrej na 200 °C. Zemiaky ošúp, nakrájaj na menšie kocky, osoľ a daj na plech s papierom na pečenie.","Kuracie prsia prekroj pozdĺžne na tenšie rezne, osoľ a okoreň. Polož ich na plech vedľa zemiakov.","Daj piecť na 15 minút. Potom plech vyber, na mäso ulož plátky mozzarelly a prekrojené paradajky posypané bazalkou.","Vráť do rúry na ďalších 10 minút, kým sa syr neroztopí a zemiaky nie sú mäkké."],t:["mealprep","mikrovlnka"]},
{id:"ck17",n:"Kurací wrap s čedarom a jogurtom",c:"obed",p:25,s:2,k:564,pr:52,ca:35,f:24,tm:20,
ing:["300 g kuracích pŕs","2 veľké celozrnné tortilly","60 g syra čedar (nastrúhaného)","100 g bieleho gréckeho jogurtu","hrsť šalátu a nakrájaná uhorka","1 PL olivového oleja","soľ, gyros korenie"],
st:["Kuracie mäso nakrájaj na malé kúsky, posyp gyros korením a opeč na panvici s olejom dozlatista.","Jogurt zmiešaj so štipkou soli a čiernym korením (môžeš pridať pretlačený cesnak).","Tortillu nasucho nahrej. Do stredu natri jogurtový dresing, ulož šalát, uhorku, orestované mäso a posyp čedarom.","Pevne zabaľ a ulož do krabičiek."],t:["mealprep","rychle","studene"]},
{id:"ck18",n:"Morčacie chilli s červenou fazuľou",c:"obed",p:26,s:2,k:523,pr:44,ca:62,f:11,tm:25,
ing:["300 g mletého morčacieho mäsa","200 g červenej fazule z konzervy (prepláchnutej)","400 g lúpaných paradajok (1 plechovka)","100 g ryže (v surovom stave)","1 cibuľa a 1 strúčik cesnaku","soľ, chilli korenie, sladká paprika"],
st:["Ryžu daj variť podľa návodu na obale. Cibuľu a cesnak nasekaj nadrobno.","Na panvici (nasucho, mäso pustí tuk) orestuj cibuľu, cesnak a mleté mäso. Restuj, kým mäso nezhnedne.","Zasyp chilli korením, sladkou paprikou a zalej lúpanými paradajkami. Dus na miernom ohni 10 minút.","Pridaj prepláchnutú fazuľu, nechaj ešte 2 minúty prehriať a naporcuj do krabičiek s ryžou."],t:["mealprep","mikrovlnka","pikantne"]},
{id:"ck19",n:"Vykostené stehná s pečenými batatmi",c:"obed",p:27,s:2,k:532,pr:47,ca:41,f:20,tm:35,
ing:["400 g vykostených kuracích stehien (bez kože)","400 g batatov","50 g syru Feta","1 PL olivového oleja","soľ, zmes korenia na pečené kura"],
st:["Rúru predhrej na 200 °C. Bataty ošúp, nakrájaj na hranolky, pokvapkaj olejom, osoľ a rozlož na plech.","Vykostené kuracie stehná poriadne potri zmesou korenia na pečené kura a pridaj na plech k batatom.","Peč približne 25–30 minút, kým nie je mäso prepečené a zemiaky na okrajoch chrumkavé.","Pri balení do krabičiek posyp upečené bataty rozmrvenou Fetou."],t:["mealprep","mikrovlnka"]},
{id:"ck20",n:"Kuracie mäso s cestovinami a pestom",c:"obed",p:28,s:2,k:554,pr:50,ca:57,f:14,tm:20,
ing:["350 g kuracích pŕs","150 g cestovín (penne alebo fusilli)","50 g bazalkového pesta (v poháriku)","100 g cherry paradajok","soľ, čierne korenie"],
st:["Cestoviny uvar v osolenej vode podľa návodu (al dente). Tesne pred zliatím si odlož pol deci vody z cestovín.","Kuracie prsia nakrájaj na kocky, osoľ, okoreň a sprudka opeč na suchej panvici dozlatista.","K mäsu pridaj uvarené cestoviny, bazalkové pesto, prekrojené paradajky a trošku odloženej vody z cestovín.","Všetko poriadne premiešaj na miernom ohni, kým pesto neobalí cestoviny, a rozdeľ do krabičiek."],t:["mealprep","mikrovlnka","rychle"]},

{id:"ck21",n:"Hovädzie rezančeky na ázijský spôsob",c:"obed",p:30,s:2,k:608,pr:53,ca:63,f:16,tm:15,
ing:["400 g chudého hovädzieho mäsa (roštenec alebo zadné)","150 g ryže (v surovom stave)","150 g mrazenej ázijskej zeleniny","2 PL tmavej sójovej omáčky","1 PL sezamového alebo olivového oleja","soľ, čierne korenie"],
st:["Ryžu daj variť podľa návodu v osolenej vode.","Hovädzie mäso nakrájaj na tenké, krátke rezančeky a zľahka okoreň.","Na panvici rozpáľ olej a mäso sprudka opeč (stačia 3–4 minúty, aby nebolo gumené). Pridaj zeleninu a opekaj ďalšie 3 minúty.","Zalej sójovou omáčkou, poriadne premiešaj a odstav. Rozdeľ do krabičiek spolu s ryžou."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck22",n:"Hovädzie fašírky s pečenými batatmi",c:"obed",p:31,s:2,k:575,pr:43,ca:40,f:27,tm:35,
ing:["400 g chudého mletého hovädzieho mäsa (max 10–15 % tuku)","400 g batatov","1 PL olivového oleja","1 ČL sušeného cesnaku a mletej papriky","soľ, čierne korenie"],
st:["Rúru predhrej na 200 °C. Bataty ošúp, nakrájaj na kocky, pokvapkaj polovicou oleja, osoľ a daj na plech.","Mleté mäso zmiešaj v miske so soľou, cesnakom a čiernym korením. Vytvaruj 4 až 6 hrubších fašírok.","Fašírky potri zvyšným olejom a ulož na plech vedľa batatov.","Peč všetko spolu 20–25 minút. Mäso pustí šťavu, ktorou môžeš na záver poliať zemiaky v krabičke."],t:["mealprep","mikrovlnka"]},
{id:"ck23",n:"Bravčové karé s ryžou a fazuľkou",c:"obed",p:32,s:2,k:630,pr:52,ca:65,f:18,tm:20,
ing:["400 g chudého bravčového karé","150 g ryže (v surovom stave)","200 g zelených fazuľových luskov (mrazených alebo čerstvých)","1 PL olivového oleja","soľ, mletá rasca, čierne korenie"],
st:["Ryžu uvar do mäkka. Fazuľové lusky spar vo vriacej osolenej vode (cca 5 minút) a zlej.","Bravčové karé nakrájaj na plátky (alebo rezance), jemne naklep, osoľ a posyp rascou.","Na rozpálenej panvici s olejom opeč mäso z oboch strán dozlatista (cca 4 minúty z každej strany).","Do výpeku na panvici hoď na minútu zelené fazuľky, premiešaj a rozdeľ do krabičiek spolu s ryžou a mäsom."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck24",n:"Mleté hovädzie s kuskusom a cuketou",c:"obed",p:33,s:2,k:656,pr:50,ca:51,f:28,tm:20,
ing:["400 g mletého hovädzieho mäsa","120 g kuskusu (v surovom stave)","1 menšia cuketa (cca 200 g)","100 g lúpaných paradajok z konzervy","1 PL olivového oleja","soľ, oregano, čierne korenie"],
st:["Kuskus zalej vriacou vodou (tesne nad povrch kuskusu), prikry a nechaj 5 minút napučať.","Na panvici s olejom orestuj mleté mäso. Keď stratí ružovú farbu, pridaj na malé kocky nakrájanú cuketu.","Restuj spolu 5 minút. Pridaj lúpané paradajky, soľ, oregano a dus ďalších 5 minút.","Mäsovú zmes s cuketou podávaj v krabičkách vedľa hotového kuskusu."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck25",n:"Rýchle Chilli con Carne s ryžou",c:"obed",p:34,s:2,k:657,pr:47,ca:79,f:17,tm:25,
ing:["300 g mletého hovädzieho mäsa","200 g červenej fazule (z konzervy, prepláchnutej)","100 g kukurice (z konzervy)","400 g lúpaných paradajok (1 plechovka)","120 g ryže (v surovom stave)","chilli korenie, sladká paprika, soľ"],
st:["Ryžu uvar vo vode podľa návodu.","Na suchej panvici (mäso pustí svoj tuk) orestuj hovädzie mäso dohneda. Pridaj chilli a papriku.","Zalej lúpanými paradajkami a nechaj na miernom ohni zhustnúť (cca 10 minút).","Vmiešaj prepláchnutú fazuľu a kukuricu, prehrej 2 minúty a porciuj do krabičiek k ryži."],t:["mealprep","mikrovlnka","pikantne"]},
{id:"ck26",n:"Hovädzí wrap s avokádom a čedarom",c:"obed",p:35,s:2,k:641,pr:42,ca:35,f:37,tm:20,
ing:["300 g mletého hovädzieho mäsa","2 veľké celozrnné tortilly","1 zrelé avokádo (čistá váha cca 120 g)","50 g syra čedar (nastrúhaného)","hrsť čerstvého šalátu","soľ, čierne korenie, mletá paprika"],
st:["Mleté mäso orestuj na suchej panvici. Osoľ, okoreň a pridaj mletú papriku. Odstav, keď je prepečené a šťava sa odparí.","Avokádo ošúp, roztlač vidličkou a jemne osoľ.","Tortillu zľahka nahrej. Do stredu natri avokádo, pridaj šalát, horúce mäso a posyp čedarom.","Zabaľ pevne do wrapu. Pre lepšiu chuť ho nasucho opeč z oboch strán na panvici."],t:["mealprep","rychle","studene"]},
{id:"ck27",n:"Bravčová panenka s pečenými zemiakmi",c:"obed",p:36,s:2,k:494,pr:48,ca:44,f:14,tm:40,
ing:["400 g bravčovej panenky (najchudšie bravčové mäso)","500 g zemiakov","100 g cherry paradajok","1 PL olivového oleja","soľ, zmes korenia na pečené mäso"],
st:["Rúru predhrej na 200 °C. Zemiaky ošúp, nakrájaj na mesiačiky, pokvapkaj polovicou oleja, osoľ a daj na plech.","Bravčovú panenku v celku potri druhou polovicou oleja, osoľ a obaľ v korení.","Panenku sprudka opeč na panvici z každej strany dohneda (aby sa zatiahla). Potom ju prelož na plech k zemiakom.","Peč v rúre cca 20 minút. Na posledných 5 minút pridaj k zemiakom cherry paradajky. Mäso pred balením nakrájaj na medailóniky."],t:["mealprep","mikrovlnka"]},
{id:"ck28",n:"Hovädzí steak s brokolicou a ryžou",c:"obed",p:37,s:2,k:577,pr:54,ca:52,f:17,tm:20,
ing:["400 g hovädzej roštenky (alebo iného mäsa na steak)","120 g ryže (v surovom stave)","300 g brokolice","1 PL masla (15 g)","hrubozrnná soľ, čierne korenie"],
st:["Ryžu uvar podľa návodu. Brokolicu uvar vo vriacej osolenej vode do mäkka (cca 5 minút).","Mäso vyber z chladničky aspoň 15 minút pred pečením. Poriadne ho osoľ a okoreň.","Na panvici rozpáľ maslo (alebo olej). Steaky opekaj sprudka 3–4 minúty z každej strany (podľa preferencie prepečenia).","Mäso nechaj 5 minút odpočinúť, nakrájaj na plátky a rozdeľ do krabičiek k ryži a brokolici."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck29",n:"Hovädzie rezance na šampiňónoch s cestovinou",c:"obed",p:38,s:2,k:592,pr:56,ca:55,f:16,tm:30,
ing:["400 g hovädzieho zadného mäsa (nakrájaného na rezance)","150 g cestovín (penne alebo fusilli)","200 g čerstvých šampiňónov","1 PL olivového oleja","soľ, mleté čierne korenie, drvená rasca"],
st:["Cestoviny uvar v osolenej vode al dente.","Na panvici rozpáľ olej a sprudka orestuj hovädzie rezance. Osoľ, okoreň a pridaj rascu.","Keď je mäso zatiahnuté, pridaj na plátky nakrájané šampiňóny. Restuj, kým huby nepustia vodu a nezmäknú.","Podlej trochou vody (alebo hovädzím vývarom), povar ešte 5 minút a hotovú zmes s omáčkou daj do krabičiek na cestoviny."],t:["mealprep","mikrovlnka"]},
{id:"ck30",n:"Mäsové guľky s paradajkovou omáčkou",c:"obed",p:39,s:2,k:670,pr:39,ca:61,f:30,tm:30,
ing:["300 g mix mletého mäsa (hovädzie/bravčové)","150 g cestovín (v surovom stave)","400 g lúpaných paradajok z konzervy","1 PL olivového oleja","soľ, oregano, 1 strúčik cesnaku"],
st:["Cestoviny uvar podľa návodu. Z mletého mäsa, soli a korenia vyformuj menšie guľky.","Na oleji orestuj pretlačený cesnak a zľahka opeč mäsové guľky zo všetkých strán, kým nezhnednú.","Zalej ich lúpanými paradajkami, roztlač ich varechou na omáčku, pridaj oregano a soľ.","Prikry pokrievkou a dus na miernom ohni 10–15 minút. Podávaj v krabičke na uvarených cestovinách."],t:["mealprep","mikrovlnka"]},

{id:"ck31",n:"Pečený losos s ryžou a špargľou",c:"obed",p:41,s:2,k:622,pr:48,ca:58,f:22,tm:25,
ing:["400 g lososového filetu","150 g ryže (v surovom stave)","300 g čerstvej špargle","1 PL olivového oleja","soľ, mleté čierne korenie, citrónová šťava"],
st:["Ryžu uvar v osolenej vode podľa návodu. Špargľu umy, odtrhni drevnaté konce a pokvapkaj olejom.","Lososa osoľ, okoreň a poukladaj na plech spolu so špargľou.","Peč v predhriatej rúre pri 200 °C približne 12–15 minút, kým nie je losos prepečený.","Hotové jedlo rozdeľ rovnomerne do dvoch krabičiek spolu s ryžou a pokvapkaj citrónom."],t:["mealprep","mikrovlnka"]},
{id:"ck32",n:"Tuniakový šalát s varenými zemiakmi",c:"obed",p:42,s:2,k:512,pr:48,ca:44,f:16,tm:30,
ing:["3 konzervy tuniaka vo vlastnej šťave (celková čistá váha cca 390 g)","500 g zemiakov","150 g bieleho gréckeho jogurtu","1 PL olivového oleja","1 menšia červená cibuľa","soľ, čierne korenie"],
st:["Zemiaky ošúp, nakrájaj na kocky a uvar v osolenej vode do mäkka (cca 15 minút). Potom ich nechaj vychladnúť.","V miske zmiešaj odkvapkaného tuniaka, grécky jogurt, nadrobno nakrájanú cibuľu a olivový olej.","Pridaj vychladené zemiaky, osoľ, okoreň a jemne premiešaj, aby sa zemiaky nerozpadli.","Rozdeľ rovnomerne do dvoch krabičiek."],t:["mealprep","studene"]},
{id:"ck33",n:"Krevetové rezance na cesnaku a masle",c:"obed",p:43,s:2,k:535,pr:42,ca:58,f:15,tm:25,
ing:["400 g mrazených kreviet (očistených, predvarených)","120 g rezancov (soba alebo ryžové rezance)","2 strúčiky cesnaku","20 g masla a 1 PL olivového oleja","2 hrste baby špenátu","soľ, čierne korenie"],
st:["Rezance zalej vriacou vodou, nechaj zmäknúť podľa návodu a zlej. Krevety rozmraz a osuš.","Na panvici rozpáľ maslo s olejom, pridaj pretlačený cesnak a krevety. Opekaj len 2–3 minúty, kým nie sú ružové.","Do panvice pridaj baby špenát a uvarené rezance, premiešaj, kým špenát zvädne.","Dochuť soľou, korením a rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck34",n:"Pstruh na masle s pečenými zemiakmi",c:"obed",p:44,s:2,k:526,pr:44,ca:38,f:22,tm:35,
ing:["400 g pstruhových filetov (s kožou)","400 g zemiakov","20 g masla","1 PL olivového oleja","soľ, mleté čierne korenie, petržlenová vňať"],
st:["Rúru predhrej na 200 °C. Zemiaky nakrájaj na mesiačiky, pokvapkaj olejom, osoľ a rozlož na plech. Peč 25 minút.","Filety pstruha osoľ, okoreň a nasekaj petržlenovú vňať.","Na panvici rozpáľ maslo a opekaj filety najskôr kožou nadol (cca 4 minúty), potom otoč a dopeč 2 minúty.","Rybu a upečené zemiaky rozdeľ do pripravených krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck35",n:"Lososové guľky s kuskusom",c:"obed",p:45,s:2,k:573,pr:45,ca:51,f:21,tm:30,
ing:["400 g mletého lososa (alebo nasekaného na veľmi jemno)","120 g kuskusu (v surovom stave)","1 vajce","1 PL olivového oleja","soľ, citrónová kôra, kôpor alebo petržlenová vňať"],
st:["Kuskus zalej vriacou vodou, prikry a nechaj napučať 5 minút.","V miske zmiešaj mletého lososa, vajce, bylinky, citrónovú kôru a štipku soli. Vyformuj menšie guľky.","Na panvici s olejom opekaj guľky zo všetkých strán do zlatista a chrumkava (cca 10 minút).","Do krabičiek nalož kuskus a navrch ulož upečené lososové guľky."],t:["mealprep","mikrovlnka"]},
{id:"ck36",n:"Krevety s ryžou na ázijský spôsob",c:"obed",p:46,s:2,k:518,pr:44,ca:63,f:10,tm:20,
ing:["400 g mrazených kreviet (očistených)","150 g ryže (v surovom stave)","150 g mrazenej zeleninovej zmesi (mrkva, hrášok, kukurica)","2 PL sójovej omáčky","1 PL sezamového oleja","soľ, cesnakový prášok"],
st:["Ryžu uvar v osolenej vode. Zeleninu krátko prepláchni v horúcej vode.","Na panvici rozpáľ sezamový olej, pridaj krevety, cesnakový prášok a opekaj 3 minúty.","Ku krevetám prisyp zeleninu a zalej sójovou omáčkou, premiešaj a prehrej ďalšie 2 minúty.","Zmes kreviet so zeleninou zmiešaj s ryžou alebo rozdeľ do krabičiek zvlášť."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck37",n:"Tuniakový steak s pečenými batatmi",c:"obed",p:47,s:2,k:519,pr:52,ca:35,f:19,tm:30,
ing:["400 g tuniakových steakov (2 ks)","300 g batatov (sladkých zemiakov)","1 PL olivového oleja","soľ, mleté čierne korenie, citrónová šťava"],
st:["Rúru predhrej na 200 °C. Bataty nakrájaj na hranolky, pokvapkaj olejom, osoľ a peč na plechu 20 minút.","Tuniakové steaky osuš papierovou utierkou, osoľ a okoreň z oboch strán.","Na rozpálenej panvici opekaj tuniaka z každej strany presne 1,5 až 2 minúty (stred by mal zostať ružový, aby nevyschol).","Nakrájaj na plátky a ulož do krabičiek k pečeným batatom."],t:["mealprep","mikrovlnka"]},
{id:"ck38",n:"Treska zapekaná so syrom a zemiakmi",c:"obed",p:48,s:2,k:514,pr:50,ca:38,f:18,tm:30,
ing:["400 g filetov z tresky","400 g zemiakov","80 g syra eidam (nastrúhaného)","1 PL olivového oleja","soľ, mletá červená paprika, čierne korenie"],
st:["Zemiaky uvar v šupke, potom ich ošúp a nakrájaj na kolieska.","Filety tresky osoľ, okoreň a posyp mletou paprikou.","Do zapekacej misy (alebo priamo do sklenených krabičiek vhodných do rúry) poukladaj vrstvu zemiakov, na ňu tresku a posyp syrom.","Peč v rúre pri 190 °C asi 20 minút, kým sa syr neroztopí a nezhnedne."],t:["mealprep","mikrovlnka"]},
{id:"ck39",n:"Cestoviny s morskými plodmi a paradajkami",c:"obed",p:49,s:2,k:498,pr:44,ca:58,f:10,tm:20,
ing:["400 g mrazenej zmesi morských plodov","150 g cestovín (penne alebo fusilli)","200 g lúpaných paradajok z konzervy","2 strúčiky cesnaku","1 PL olivového oleja","soľ, bazalka, čierne korenie"],
st:["Cestoviny uvar al dente v osolenej vode. Morské plody nechaj rozmraziť a dobre osuš.","Na panvici s olejom orestuj pretlačený cesnak, pridaj morské plody a opekaj 3 minúty.","Zalej lúpanými paradajkami, pridaj bazalku, soľ a korenie. Povar na miernom ohni 5 minút.","Zmiešaj omáčku s morskými plodmi a cestovinami, rozdeľ do krabičiek."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck40",n:"Pečený losos s quinoou a cuketou",c:"obed",p:50,s:2,k:562,pr:48,ca:43,f:22,tm:25,
ing:["400 g lososového filetu","120 g quinoy (v surovom stave)","200 g cukety","1 PL olivového oleja","soľ, citrónové korenie"],
st:["Quinou prepláchni v horúcej vode a uvar v dvojnásobnom množstve vody (cca 12–15 minút).","Cuketu nakrájaj na polmesiačiky. Lososa osoľ a posyp citrónovým korením.","Na plech s papierom na pečenie poukladaj lososa, cuketu, pokvapkaj olejom a peč pri 200 °C asi 15 minút.","Hotovú quinou rozdeľ do krabičiek spolu s pečeným lososom a cuketou."],t:["mealprep","mikrovlnka"]},

{id:"ck41",n:"Kuracie prsia a zemiaky z jedného plechu",c:"obed",p:52,s:2,k:460,pr:51,ca:43,f:10,tm:35,
ing:["400 g kuracích pŕs","500 g zemiakov","1 PL olivového oleja","soľ, mletá červená paprika, čierne korenie"],
st:["Rúru predhrej na 200 °C. Zemiaky ošúp, nakrájaj na mesiačiky a kuracie prsia nakrájaj na väčšie kocky.","Všetko rozlož na plech vystlaný papierom na pečenie.","Pokvapkaj olivovým olejom, osoľ, okoreň a posyp mletou paprikou. Dôkladne premiešaj priamo na plechu.","Peč v rúre približne 30 minút, kým nie sú zemiaky mäkké a mäso prepečené. Rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck42",n:"Bravčové karé so zemiakmi z plechu",c:"obed",p:53,s:2,k:458,pr:48,ca:34,f:14,tm:40,
ing:["400 g chudého bravčového karé","400 g zemiakov","1 PL olivového oleja","soľ, drvená rasca, čierne korenie"],
st:["Rúru predhrej na 200 °C. Zemiaky nakrájaj na kocky a bravčové karé na hrubšie plátky.","Všetko poukladaj na plech, pokvapkaj olejom, osoľ, posyp rascou a čiernym korením.","Peč v rúre približne 30 minút, kým mäso a zemiaky nie sú zlatisté a mäkké.","Hotové porcie rozdeľ do dvoch pripravených krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck43",n:"Morčacie prsia so zeleninou z plechu",c:"obed",p:54,s:2,k:330,pr:49,ca:12,f:10,tm:35,
ing:["400 g morčacích pŕs","400 g miešanej zeleniny (mrkva, paprika, cuketa)","1 PL olivového oleja","soľ, sušený cesnak, oregano"],
st:["Rúru predhrej na 200 °C. Morčacie prsia a zeleninu nakrájaj na rovnomerne veľké kúsky.","Rozlož všetko na plech, pokvapkaj olejom, osoľ, pridaj cesnak a oregano.","Poriadne premiešaj a peč v rúre približne 25 minút, kým zelenina nezmäkne a mäso sa neopečie.","Rozdeľ rovnomerne do dvoch krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck44",n:"Klobása a zemiaky z jedného plechu",c:"obed",p:55,s:2,k:617,pr:28,ca:44,f:37,tm:40,
ing:["300 g kvalitnej domácej klobásy (s vysokým podielom mäsa)","500 g zemiakov","1 PL olivového oleja","soľ, mletá červená paprika, majorán"],
st:["Rúru predhrej na 200 °C. Zemiaky nakrájaj na mesiačiky a klobásu na kolieska alebo hrubšie polmesiace.","Rozlož na plech, pokvapkaj olejom, osoľ, posyp paprikou a majoránom.","Peč približne 30 minút, kým nie sú zemiaky chrumkavé a klobása upečená.","Rozdeľ na dve rovnaké porcie do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck45",n:"Hovädzie fašírky a pečená zelenina z plechu",c:"obed",p:56,s:2,k:457,pr:44,ca:14,f:25,tm:25,
ing:["400 g chudého mletého hovädzieho mäsa","400 g zeleniny (brokolica a mrkva)","1 PL olivového oleja","soľ, čierne korenie, mletá rasca"],
st:["Rúru predhrej na 200 °C. Mleté mäso ochuť soľou a korením, vyformuj z neho menšie ploché fašírky.","Brokolicu rozober na ružičky a mrkvu nakrájaj na kolieska.","Fašírky a zeleninu poukladaj na plech, zeleninu pokvapkaj olejom a osoľ.","Peč v rúre cca 25 minút, kým nie je mäso prepečené. Rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck46",n:"Kuracie stehná a bataty z plechu",c:"obed",p:57,s:2,k:509,pr:39,ca:40,f:21,tm:40,
ing:["400 g vykostených kuracích stehien (bez kože)","400 g batatov (sladkých zemiakov)","1 PL olivového oleja","soľ, grilovacie korenie"],
st:["Rúru predhrej na 200 °C. Bataty ošúp a nakrájaj na kocky. Kuracie stehná očisti a posyp grilovacím korením.","Rozlož bataty a mäso na plech vystlaný papierom na pečenie.","Bataty pokvapkaj olejom a jemne osoľ.","Peč všetko spolu v rúre približne 30 minút, kým nie sú bataty mäkké a mäso upečené. Rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck47",n:"Bravčová panenka a bataty z plechu",c:"obed",p:58,s:2,k:465,pr:47,ca:40,f:13,tm:35,
ing:["400 g bravčovej panenky","400 g batatov","1 PL olivového oleja","soľ, rozmarín, čierne korenie"],
st:["Rúru predhrej na 200 °C. Bataty nakrájaj na mesiačiky. Panenku v celku osoľ, okoreň a posyp rozmarínom.","Na plech poukladaj bataty (pokvapkaj ich polovicou oleja) a vedľa nich polož panenku (potretú zvyšným olejom).","Peč v rúre približne 20–25 minút. Mäso nechaj chvíľu odpočinúť, nakrájaj na plátky a rozdeľ k batatom do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck48",n:"Kurací fajita plech s ryžou",c:"obed",p:59,s:2,k:514,pr:53,ca:54,f:10,tm:30,
ing:["400 g kuracích pŕs","300 g farebných paprík a cibule (nakrájaných na rezance)","120 g ryže (v surovom stave)","1 PL olivového oleja","soľ, mletá paprika, mexické korenie / chilli"],
st:["Ryžu uvar v osolenej vode podľa návodu. Rúru predhrej na 200 °C.","Kuracie prsia a zeleninu nakrájaj na rezance. Rozlož na plech.","Pokvapkaj olejom, posyp soľou, paprikou a mexickým korením. Dôkladne premiešaj.","Peč v rúre 20 minút. Hotovú zmes rozdeľ do krabičiek spolu s uvarenou ryžou."],t:["mealprep","mikrovlnka","pikantne"]},
{id:"ck49",n:"Morčacie prsia, zemiaky a šampiňóny z plechu",c:"obed",p:60,s:2,k:440,pr:52,ca:37,f:9,tm:40,
ing:["400 g morčacích pŕs","400 g zemiakov (ideálne menších v šupke, umytých)","200 g šampiňónov","1 PL olivového oleja","soľ, čierne korenie, tymian"],
st:["Rúru predhrej na 200 °C. Zemiaky prekroj na polovice, šampiňóny na štvrtiny a morčacie prsia na kocky.","Všetko vysyp na plech, pokvapkaj olivovým olejom, osoľ, okoreň a pridaj tymian.","Dôkladne premiešaj a peč v rúre zhruba 30 minút, kým nie sú zemiaky mäkké.","Rozdeľ rovnomerne do dvoch krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck50",n:"Zapekané kuracie prsia so slaninou a syrom z plechu",c:"obed",p:61,s:2,k:739,pr:68,ca:34,f:37,tm:40,
ing:["400 g kuracích pŕs","400 g zemiakov (nakrájaných na kocky)","80 g chudej slaniny (plátky)","80 g syra eidam (nastrúhaného)","1 PL olivového oleja","soľ, čierne korenie"],
st:["Rúru predhrej na 200 °C. Zemiaky rozlož na plech, pokvapkaj olejom a osoľ. Kuracie prsia nakrájaj na plátky a poukladaj k zemiakom.","Peč zemiaky s mäsom približne 20 minút.","Potom plech vyber, na každé kuracie prso polož plátok slaniny a posyp nastrúhaným eidamom.","Vráť do rúry na 10 minút, kým sa syr neroztopí a slanina nie je chrumkavá. Rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},

{id:"ck51",n:"Kuracie rezance so zeleninou z panvice",c:"obed",p:63,s:2,k:517,pr:52,ca:53,f:11,tm:17,
ing:["400 g kuracích pŕs","300 g miešanej zeleniny (mrkva, hrášok, kukurica)","120 g ryže (v surovom stave)","1 PL olivového oleja","soľ, mleté čierne korenie"],
st:["Ryžu uvar v osolenej vode podľa návodu na obale.","Kuracie prsia nakrájaj na tenké rezance, osoľ a okoreň.","Na panvici rozpáľ olivový olej a kuracie rezance sprudka opekaj asi 5–7 minút do zlatista.","Pridaj miešanú zeleninu, podlej troškou vody a dus spolu 5 minút. Zmiešaj s uvarenou ryžou a rozdeľ do krabičiek."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck52",n:"Bravčové rezance s paprikou na panvici",c:"obed",p:64,s:2,k:489,pr:48,ca:38,f:15,tm:15,
ing:["400 g chudého bravčového karé","2 farebné papriky (nakrájané na rezance)","100 g ryže (v surovom stave)","1 PL olivového oleja","soľ, mletá červená paprika"],
st:["Ryžu uvar v osolenej vode. Bravčové karé nakrájaj na tenké rezance.","Na panvici rozpáľ olej, pridaj bravčové rezance a opekaj do zatiahnutia (cca 4 minúty).","Pridaj nakrájané papriky, posyp mletou paprikou a soľou.","Opekaj za stáleho miešania ďalších 5 minút, kým paprika nezmäkne. Podávaj s ryžou."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck53",n:"Mleté hovädzie s fazuľou z jednej panvice",c:"obed",p:65,s:2,k:536,pr:45,ca:50,f:17,tm:15,
ing:["350 g chudého mletého hovädzieho mäsa","200 g červenej fazule (z konzervy, prepláchnutej)","100 g ryže (v surovom stave)","100 g pretlaku alebo lúpaných paradajok","1 PL olivového oleja","soľ, čierne korenie, chilli"],
st:["Ryžu uvar klasickým spôsobom v osolenej vode.","Na panvici rozpáľ olej a orestuj mleté hovädzie mäso, kým nestratí ružovú farbu.","Pridaj paradajkový pretlak, prepláchnutú fazuľu, soľ, korenie a chilli.","Premiešaj a prehrej na miernom ohni asi 5 minút. Zmiešaj s ryžou alebo rozdeľ do krabičiek zvlášť."],t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"ck54",n:"Morčacie mäso so špenátom a smotanou",c:"obed",p:66,s:2,k:455,pr:53,ca:32,f:11,tm:15,
ing:["400 g morčacích pŕs","150 g čerstvého baby špenátu","100 ml smotany na varenie (12%)","100 g ryže (v surovom stave)","1 ČL masla (5 g)","soľ, cesnakový prášok"],
st:["Ryžu uvar v osolenej vode. Morčacie prsia nakrájaj na kocky, osoľ a posyp cesnakom.","Na panvici rozpáľ maslo a morčacie kocky opeč do zlatista (cca 6 minút).","Pridaj baby špenát a nechaj ho na panvici zvädnúť.","Zalej smotanou, nechaj prebublať 2 minúty a odstav. Rozdeľ do krabičiek s ryžou."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck55",n:"Klobása s vajcami a cibuľou z panvice",c:"obed",p:67,s:2,k:588,pr:37,ca:35,f:33,tm:15,
ing:["250 g kvalitnej klobásy (nakrájanej na kolieska)","6 vajec","1 stredná cibuľa","2 plátky kváskového chleba (cca 100 g)","1 ČL masla (5 g)","soľ, čierne korenie"],
st:["Na panvici roztop maslo a orestuj nadrobno nakrájanú cibuľu spolu s kolieskami klobásy do chrumkava.","V miske rozšľahaj vajcia so soľou a korením.","Vylej vajcia priamo na klobásu s cibuľou a za stáleho miešania rob na panvici praženicu, kým vajcia stuhnú.","Rozdeľ do krabičiek a prilož plátok chleba k obom porciám."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck56",n:"Kuracie prsia s cuketou a paradajkami",c:"obed",p:68,s:2,k:445,pr:53,ca:34,f:10,tm:15,
ing:["400 g kuracích pŕs","1 menšia cuketa (nakrájaná na kocky)","150 g cherry paradajok (prekrojených)","100 g ryže (v surovom stave)","1 PL olivového oleja","soľ, oregano"],
st:["Ryžu uvar v osolenej vode. Kuracie prsia nakrájaj na kocky.","Na panvici rozpáľ olivový olej a kuracie mäso sprudka opeč (5 minút).","Pridaj nakrájanú cuketu a cherry paradajky, osoľ a posyp oreganom.","Dus spoločne asi 5 minút, kým zelenina pustí šťavu a zmäkne. Podávaj s uvarenou ryžou."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck57",n:"Hovädzie rezančeky s hráškom na panvici",c:"obed",p:69,s:2,k:512,pr:52,ca:53,f:11,tm:25,
ing:["400 g chudého hovädzieho mäsa (nakrájaného na rezance)","200 g zeleného hrášku (mrazeného)","120 g ryže (v surovom stave)","1 PL olivového oleja","soľ, mleté čierne korenie, cesnakový prášok"],
st:["Ryžu uvar klasicky v osolenej vode. Hrášok prepláchni teplou vodou.","Na panvici rozpáľ olej a hovädzie rezance opekaj sprudka asi 4–5 minút.","Pridaj zelený hrášok, osoľ, okoreň a prisyp cesnakový prášok.","Podlej trochou vody a dus spolu 4 minúty. Zmiešaj s ryžou a naporcuj."],t:["mealprep","mikrovlnka"]},
{id:"ck58",n:"Bravčové karé s hubami z panvice",c:"obed",p:70,s:2,k:462,pr:50,ca:34,f:13,tm:17,
ing:["400 g chudého bravčového karé","200 g šampiňónov (nakrájaných na plátky)","100 g ryže (v surovom stave)","1 PL olivového oleja","soľ, mletá rasca, čierne korenie"],
st:["Ryžu uvar v osolenej vode. Bravčové karé nakrájaj na menšie plátky alebo kocky.","Na panvici rozpáľ olej a mäso opeč z každej strany dozlatista.","Pridaj plátky šampiňónov, posyp rascou, soľou a korením.","Opekaj spolu, kým šampiňóny pustia šťavu a zmäknú (cca 6 minút). Podávaj s ryžou."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck59",n:"Morčacie kocky so žltou kari omáčkou",c:"obed",p:71,s:2,k:485,pr:53,ca:52,f:9,tm:15,
ing:["400 g morčacích pŕs","120 g ryže (v surovom stave)","100 ml kokosového mlieka (alebo smotany)","1 ČL žltého kari korenia","1 PL olivového oleja","soľ, korenie"],
st:["Ryžu uvar klasickým spôsobom. Morčacie prsia nakrájaj na kocky.","Na panvici rozpáľ olej, pridaj morčacie kocky a opekaj 5 minút.","Posyp kari korením, osoľ, okoreň a zalej kokosovým mliekom.","Povar na miernom ohni 3 minúty, kým omáčka mierne zhustne. Rozdeľ do krabičiek s ryžou."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck60",n:"Fitness panvica s mletým mäsom a kukuricou",c:"obed",p:72,s:2,k:531,pr:45,ca:55,f:16,tm:15,
ing:["350 g chudého mletého bravčového alebo morčacieho mäsa","150 g kukurice (z konzervy)","120 g ryže (v surovom stave)","1 PL olivového oleja","soľ, mletá paprika, čierne korenie"],
st:["Ryžu uvar v osolenej vode.","Na panvici rozpáľ olej a orestuj mleté mäso dohneda.","Pridaj kukuricu, osoľ, okoreň a posyp mletou paprikou.","Premiešaj a prehrej na panvici asi 3–4 minúty. Zmiešaj s uvarenou ryžou a naplň krabičky."],t:["mealprep","mikrovlnka","rychle"]},

{id:"ck61",n:"Domáci hovädzí burger v krabičke",c:"vecera",p:74,s:2,k:559,pr:43,ca:36,f:27,tm:20,
ing:["300 g chudého mletého hovädzieho mäsa","2 celozrnné žemle (spolu cca 150 g)","40 g syra čedar (2 plátky)","2 PL ľahkej majonézy alebo jogurtového dresingu","hrsť šalátu a 1 paradajka","soľ, hrubozrnné čierne korenie"],
st:["Z mletého mäsa vytvaruj dve rovnako veľké placky (fašírky). Zľahka v strede urob palcom priehlbinu, aby sa nenafúkli.","Sprudka ich opeč na suchej panvici (z každej strany cca 3–4 minúty). Poriadne osoľ a okoreň.","Po otočení ulož na mäso plátok čedaru, aby sa roztopil. Žemle prekroj a nasucho opeč.","Žemle natri dresingom, ulož šalát, paradajku, mäso so syrom a zabaľ (prekrojené napoly) do krabičiek."],t:["mealprep","rychle"]},
{id:"ck62",n:"Kuracia quesadilla so syrom",c:"vecera",p:75,s:2,k:512,pr:49,ca:34,f:20,tm:20,
ing:["300 g kuracích pŕs","2 veľké celozrnné tortilly","80 g syra čedar (nastrúhaného)","50 g kukurice z konzervy","1 PL olivového oleja","mexické korenie, soľ"],
st:["Kuracie prsia nakrájaj na drobné kocky, posyp mexickým korením a sprudka opeč na oleji. Pridaj kukuricu a odstav.","Na suchú panvicu polož tortillu. Na jednu polovicu nasyp trochu syra, pridaj mäsovú zmes a opäť zasyp syrom.","Tortillu preklop (vznikne polmesiac) a opekaj z oboch strán, kým nie je chrumkavá a syr sa neroztopí.","Hotovú quesadillu nakrájaj na trojuholníky a po vychladnutí zabaľ do krabičiek."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck63",n:"Proteínová tortilla pizza",c:"vecera",p:76,s:2,k:508,pr:41,ca:32,f:24,tm:15,
ing:["2 veľké tortilly (slúžia ako cesto)","150 ml hustého paradajkového pretlaku","200 g kvalitnej chudej šunky","150 g mozzarelly (nastrúhanej)","oregano a bazalka"],
st:["Rúru predhrej na 220 °C. Tortilly polož na plech s papierom na pečenie.","Každú tortillu potri paradajkovým pretlakom zmiešaným s oreganom a bazalkou.","Bohato oblož plátkami šunky a zasyp nastrúhanou mozzarellou.","Peč 7–10 minút, kým nie sú okraje tortilly chrumkavé a syr zlatistý. Nakrájaj a zabaľ."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck64",n:"Naložené hranolky s mletým hovädzím",c:"vecera",p:77,s:2,k:545,pr:40,ca:39,f:25,tm:35,
ing:["400 g batatov (sladkých zemiakov)","300 g chudého mletého hovädzieho mäsa","60 g syra čedar (nastrúhaného)","1 PL olivového oleja","soľ, paprika, chilli (jalapeños podľa chuti)"],
st:["Rúru predhrej na 200 °C. Bataty nakrájaj na hranolky, pokvapkaj olejom, osoľ a peč 20–25 minút do chrumkava.","Zatiaľ na suchej panvici orestuj mleté mäso. Ochuť soľou, paprikou a chilli. Odstav.","Upečené hranolky rozdeľ do krabičiek (vhodných do mikrovlnky/rúry).","Na hranolky navrstvi mäsovú zmes a bohato posyp čedarom (syr sa roztopí pri zohrievaní jedla, alebo to daj ešte na 3 minúty do rúry)."],t:["mealprep","mikrovlnka","pikantne"]},
{id:"ck65",n:"Kurací Gyros v pite s tzatziki",c:"vecera",p:78,s:2,k:515,pr:47,ca:57,f:11,tm:20,
ing:["300 g kuracích pŕs","2 väčšie grécke pita chleby (spolu 200 g)","100 g gréckeho jogurtu","1/4 šalátovej uhorky a 1 strúčik cesnaku","1 PL olivového oleja","soľ, gyros korenie"],
st:["Kuracie prsia nakrájaj na malé kúsky, obaľ v gyros korení a opeč na panvici s olejom dozlatista.","Uhorku nastrúhaj, vyžmýkaj z nej vodu a zmiešaj ju s gréckym jogurtom, pretlačeným cesnakom a soľou (rýchle tzatziki).","Pita chleby zľahka nahrej na suchej panvici a nakroj, aby vznikla kapsa.","Kapsy naplň tzatziki dresingom, kuracím mäsom a ulož do krabičiek (môžeš pridať cibuľu)."],t:["mealprep","rychle","studene"]},
{id:"ck66",n:"Chrumkavé kuracie stripsy so zemiakmi",c:"vecera",p:79,s:2,k:500,pr:42,ca:56,f:12,tm:40,
ing:["300 g kuracích pŕs","50 g nesladených kukuričných lupienkov (cornflakes)","1 vajce","400 g zemiakov","1 PL olivového oleja","soľ, sušený cesnak, mletá paprika"],
st:["Rúru predhrej na 200 °C. Zemiaky nakrájaj na hranolky, pokvapkaj olejom a osoľ. Rozlož na polovicu plechu.","Cornflakes rozdrv v sáčku rukou na menšie kúsky a zmiešaj so soľou, cesnakom a paprikou.","Kuracie mäso nakrájaj na pásiky. Namoč ich v rozšľahanom vajíčku a obaľ v podrvených lupienkoch.","Stripsy ulož na druhú polovicu plechu a peč spolu so zemiakmi 20–25 minút dochrumkava."],t:["mealprep","mikrovlnka"]},
{id:"ck67",n:"Mac & Cheese s kuracím mäsom",c:"vecera",p:80,s:2,k:633,pr:53,ca:58,f:21,tm:25,
ing:["250 g kuracích pŕs","150 g cestovín (kolienka – macaroni)","100 g syra čedar (nastrúhaného)","100 ml polotučného mlieka","1 ČL masla (5 g)","soľ, čierne korenie"],
st:["Cestoviny uvar v osolenej vode podľa návodu. Kuracie mäso nakrájaj na drobné kocky a opeč na suchej panvici.","V hrnci, kde sa varili cestoviny, roztop maslo, zalej mliekom a nechaj zahriať.","Prisyp nastrúhaný čedar a za stáleho miešania vytvor hladkú syrovú omáčku.","Do omáčky nasyp uvarené cestoviny, orestované mäso, poriadne premiešaj a rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck68",n:"Hovädzí Philly Cheese sendvič",c:"vecera",p:81,s:2,k:570,pr:48,ca:45,f:22,tm:25,
ing:["300 g chudého hovädzieho mäsa (roštenec, falošná sviečková)","2 stredné bagety (spolu cca 150 g)","1 zelená paprika a 1 cibuľa","60 g syra provolone alebo eidam (na plátky)","1 PL olivového oleja","soľ, čierne korenie"],
st:["Hovädzie mäso nakrájaj na extrémne tenké plátky (ide to lepšie, ak ho dáš na 20 minút do mrazničky).","Na oleji orestuj na pásiky nakrájanú cibuľu a papriku. Zeleninu odhrň na kraj a sprudka opeč hovädzie plátky.","Mäso so zeleninou premiešaj, osoľ, okoreň. Zmes stiahni do dvoch kôpok a na každú polož plátky syra, nech sa roztopí.","Prekrojenú bagetu polož priamo na roztopený syr s mäsom, naber to z panvice a zabaľ."],t:["mealprep","rychle"]},
{id:"ck69",n:"Špinavá ryža s klobásou a mäsom (Dirty Rice)",c:"vecera",p:82,s:2,k:631,pr:42,ca:46,f:31,tm:30,
ing:["300 g mletého hovädzieho mäsa","100 g pikantnej klobásy (nakrájanej na malé kocky)","120 g ryže (v surovom stave)","1 zelená paprika a 1 cibuľa","cajun korenie (alebo mix mletej papriky, cesnaku a korenia)","soľ"],
st:["Ryžu uvar klasickým spôsobom.","Na suchej hlbokej panvici orestuj nakrájanú klobásu. Keď pustí tuk, pridaj nadrobno nasekanú cibuľu a papriku.","Pridaj mleté mäso a opekaj, kým nestratí ružovú farbu. Bohato zasyp cajun korením a soľou.","Do mäsovej zmesi priamo v panvici vmiešaj uvarenú ryžu. Nechaj 2 minúty prepojiť chute a zabaľ."],t:["mealprep","mikrovlnka","pikantne"]},
{id:"ck70",n:"Big Mac wrap so slaninou",c:"vecera",p:83,s:2,k:557,pr:40,ca:34,f:29,tm:20,
ing:["300 g mletého hovädzieho mäsa","2 veľké tortilly","40 g syra čedar (2 plátky)","40 g chudej slaniny","hrsť ľadového šalátu a kyslé uhorky","2 PL dresingu Thousand Island (alebo mix jogurtu, horčice a kečupu)","soľ, korenie"],
st:["Slaninu opeč dochrumkava a odlož bokom. Z mletého mäsa vytvaruj dve obdĺžnikové placky.","Placky opeč sprudka na panvici (ako na burger), osoľ, okoreň a ulož na ne plátok syra, nech sa roztopí.","Tortillu potri dresingom, polož na ňu nasekaný šalát a kolieska kyslej uhorky.","Pridaj mäso so syrom, chrumkavú slaninu a tortillu pevne zabaľ ako klasický wrap. Prekroj na polovicu."],t:["mealprep","rychle","studene"]},

{id:"ck71",n:"Grilovaný syr Halloumi s quinoou",c:"obed",p:85,s:2,k:674,pr:36,ca:65,f:30,tm:20,
ing:["200 g syra Halloumi","200 g quinoy (v surovom stave)","200 g cherry paradajok","100 g čerstvého baby špenátu","1 PL olivového oleja","soľ (len na quinou, syr je slaný dosť), oregano"],
st:["Quinou prepláchni a uvar v dvojnásobnom množstve vody (cca 15 minút).","Syr Halloumi nakrájaj na hrubšie plátky.","Na rozpálenej suchej panvici opeč plátky syra z oboch strán dozlatista. Vyber ho von.","Na rovnakej panvici s trochou oleja rýchlo orestuj prekrojené cherry paradajky a baby špenát, kým nezvädne. Zmiešaj s quinoou a ulož k tomu syr."],t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"ck72",n:"Hustý šošovicový prívarok s vajíčkami",c:"obed",p:86,s:2,k:575,pr:36,ca:65,f:19,tm:25,
ing:["200 g červenej šošovice (v surovom stave)","4 vajcia","1 cibuľa a 2 strúčiky cesnaku","1 PL olivového oleja","1 PL mletej červenej papriky a trocha octu","soľ, čierne korenie"],
st:["Vajcia uvar natvrdo (8 minút). Ošúp a prekroj na polovice.","Na oleji orestuj nadrobno nasekanú cibuľu a cesnak. Zasyp mletou paprikou a rýchlo premiešaj.","Pridaj prepláchnutú červenú šošovicu, zalej vodou (aby bola tesne ponorená) a var asi 15 minút, kým sa šošovica nerozpadne a nevytvorí hustú kašu.","Dochuť soľou, korením a lyžicou octu. Rozdeľ do krabičiek a navrch ulož vajíčka."],t:["mealprep","mikrovlnka","bezmasa"]},
{id:"ck73",n:"Cestoviny s Cottage cheese a špenátom",c:"obed",p:87,s:2,k:555,pr:36,ca:78,f:11,tm:17,
ing:["200 g cestovín (penne alebo fusilli)","400 g (2 tégliky) Cottage cheese","150 g čerstvého baby špenátu","1 strúčik cesnaku","soľ, čierne korenie"],
st:["Cestoviny uvar v osolenej vode. Tesne pred zliatím odlož trochu (cca 1 dl) horúcej vody z varenia.","Na veľkú panvicu daj na sekundu orestovať pretlačený cesnak, hneď pridaj špenát a nechaj ho zvädnúť.","Pridaj uvarené cestoviny, vodu z varenia cestovín a oba tégliky Cottage cheese.","Osoľ, okoreň a dôkladne premiešaj (už nevar, len prehrej). Zmes zhustne na krémovú omáčku. Zabaľ."],t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"ck74",n:"Tofu Tikka Masala s ryžou",c:"obed",p:88,s:2,k:620,pr:35,ca:66,f:24,tm:25,
ing:["360 g pevného bieleho tofu (2 štandardné balenia)","150 g ryže (v surovom stave)","200 g paradajkového pretlaku (alebo lúpaných paradajok)","100 ml kokosového mlieka (z plechovky)","1 PL olivového oleja","garam masala korenie (alebo kari), soľ"],
st:["Ryžu uvar klasickým spôsobom. Tofu zbav vody (osuš papierovou utierkou) a nakrájaj na kocky.","Na panvici rozpáľ olej a kocky tofu sprudka opeč dozlatista a dochrumkava.","Zasyp korením Garam masala (alebo kari), zalej paradajkovým pretlakom a kokosovým mliekom.","Nechaj 5 minút prebublať, kým omáčka nezhustne, dochuť soľou a rozdeľ do krabičiek s ryžou."],t:["mealprep","mikrovlnka","bezmasa"]},
{id:"ck75",n:"Zapekaná Feta s cícerom a paradajkami",c:"obed",p:89,s:2,k:676,pr:30,ca:85,f:24,tm:30,
ing:["150 g syra Feta (jeden blok)","1 konzerva cíceru (čistá váha cca 240 g)","300 g cherry paradajok","150 g cestovín","1 PL olivového oleja","soľ, oregano, čierne korenie"],
st:["Rúru predhrej na 200 °C. Do stredu menšieho plechu alebo zapekacej misy polož blok Fety.","Okolo Fety nasyp cherry paradajky a prepláchnutý cícer z konzervy. Pokvapkaj olejom a posyp oreganom.","Peč v rúre približne 20–25 minút. Zatiaľ uvar cestoviny.","Vyber pekáč, roztlačenú Fetu a paradajky vidličkou rozmixuj na omáčku, primiešaj uvarené cestoviny a zabaľ."],t:["mealprep","mikrovlnka","bezmasa"]},
{id:"ck76",n:"Batatovo-fazuľový Burrito Bowl s vajíčkom",c:"obed",p:90,s:2,k:669,pr:33,ca:87,f:21,tm:35,
ing:["300 g batatov","100 g quinoy alebo ryže (v surovom stave)","1 plechovka čiernej fazule (čistá váha 240 g)","1/2 zrelého avokáda","4 vajcia","1 PL olivového oleja, mexické korenie, soľ"],
st:["Bataty ošúp, nakrájaj na malé kocky, pokvapkaj polovicou oleja a upeč v rúre (20 min pri 200 °C).","Quinou uvar. Fazuľu len prepláchni teplou vodou a zľahka osoľ.","Na panvici so zvyšným olejom priprav 4 volské oká.","Do krabičiek vyskladaj vedľa seba quinou, pečené bataty, fazuľu, plátky avokáda a navrch polož volské oká."],t:["mealprep","mikrovlnka","bezmasa"]},
{id:"ck77",n:"Cícerové kari s tofu a ryžou",c:"obed",p:91,s:2,k:652,pr:37,ca:72,f:24,tm:20,
ing:["300 g pevného tofu (nakrájaného na kocky)","200 g cíceru z konzervy (prepláchnutého)","100 g ryže (v surovom stave)","100 ml kokosového mlieka","1 PL olivového oleja","žlté kari korenie, soľ"],
st:["Ryžu uvar klasickým spôsobom.","Na panvici rozpáľ olej a orestuj kocky tofu dozlatista.","Pridaj cícer, posyp bohatou dávkou kari korenia a restuj 1 minútu.","Zalej kokosovým mliekom, nechaj na miernom ohni zhustnúť (cca 5 minút), osoľ a rozdeľ do krabičiek s ryžou."],t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"ck78",n:"Hráškové rizoto s Cottage cheese",c:"obed",p:92,s:2,k:710,pr:33,ca:104,f:18,tm:30,
ing:["200 g ryže (ideálne guľatozrnnej alebo Arborio)","300 g mrazeného zeleného hrášku","150 g (3/4 téglika) Cottage cheese","50 g parmezánu (nastrúhaného)","1 PL masla (15 g)","soľ, čierne korenie"],
st:["Ryžu uvar klasicky vo vode (alebo postupným podlievaním ako rizoto).","Hrášok spar vo vriacej vode. Polovicu hrášku rozmixuj ponorným mixérom na pyré, druhú polovicu nechaj vcelku.","K uvarenej ryži priamo do hrnca vmiešaj maslo, parmezán, hráškové pyré aj celý hrášok.","Odstav z ohňa, jemne vmiešaj Cottage cheese na doplnenie bielkovín, osoľ a zabaľ do krabičiek."],t:["mealprep","mikrovlnka","bezmasa"]},
{id:"ck79",n:"Miešané Tofu à la praženica",c:"obed",p:93,s:2,k:537,pr:35,ca:34,f:29,tm:15,
ing:["360 g pevného tofu (rozdrobeného vidličkou)","1 zrelé avokádo (čistá váha cca 100 g)","2 krajce kváskového chleba (cca 100 g)","1 PL olivového oleja","1 ČL kurkumy (dodá vajíčkovú farbu)","soľ, čierne korenie"],
st:["Tofu v miske roztlač vidličkou na konzistenciu pripomínajúcu hrudkovitú praženicu.","Na panvici rozpáľ olej, nasyp tofu a restuj 3 minúty.","Posyp kurkumou, osoľ a bohato okoreň čiernym korením. Podlej lyžicou vody, aby nebolo tofu suché, a premiešaj.","Praženicu rozdeľ do krabičiek. K nej pridaj na plátky nakrájané avokádo a plátok chleba."],t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"ck80",n:"Fazuľové chilli bez mäsa (Chilli sin Carne)",c:"obed",p:94,s:2,k:615,pr:30,ca:99,f:11,tm:25,
ing:["2 konzervy červenej fazule (čistá váha 480 g)","150 g ryže (v surovom stave)","400 g lúpaných paradajok z konzervy","50 g syra čedar (nastrúhaného)","1 cibuľa","soľ, chilli korenie a sladká paprika"],
st:["Ryžu uvar vo vode podľa návodu. Fazuľu dôkladne prepláchni.","V hlbokej panvici nasucho alebo na kvapke oleja orestuj nadrobno nasekanú cibuľu.","Zalej lúpanými paradajkami, pridaj fazuľu, chilli, mletú papriku a soľ.","Nechaj 10 minút mierne bublať, kým sa chute prepoja. Naporcuj do krabičiek s ryžou a posyp čedarom (pri ohrievaní sa krásne roztopí)."],t:["mealprep","mikrovlnka","pikantne","bezmasa"]},

{id:"ck81",n:"Kurací cestovinový šalát s jogurtom",c:"obed",p:96,s:2,k:604,pr:61,ca:63,f:12,tm:25,
ing:["400 g kuracích pŕs","150 g cestovín (penne alebo fusilli, v surovom stave)","150 g bieleho gréckeho jogurtu","100 g cherry paradajok a 1/2 šalátovej uhorky","1 PL olivového oleja","soľ, čierne korenie, cesnakový prášok"],
st:["Cestoviny uvar v osolenej vode, zlej a prepláchni studenou vodou, aby vychladli.","Kuracie prsia nakrájaj na drobné kocky, osoľ, okoreň a opeč na oleji dozlatista. Nechaj vychladnúť.","Grécky jogurt zmiešaj so soľou a cesnakovým práškom. Zeleninu nakrájaj na drobné kúsky.","Vo veľkej miske zmiešaj studené cestoviny, mäso, zeleninu a jogurtový dresing. Rozdeľ do krabičiek."],t:["mealprep","studene"]},
{id:"ck82",n:"Roastbeef sendvič s horčicou",c:"obed",p:97,s:2,k:473,pr:39,ca:50,f:13,tm:10,
ing:["300 g hotového roastbeefu (alebo kvalitnej hovädzej šunky na plátky)","4 hrubšie krajce kváskového chleba (spolu cca 200 g)","2 PL plnotučnej alebo dijonskej horčice","20 g zmäknutého masla","hrsť rukoly alebo čerstvého šalátu","kyslé uhorky"],
st:["Krajce chleba natri z jednej strany tenkou vrstvou masla.","Na maslo bohato nanes vrstvu horčice.","Ulož nakrájané plátky kyslej uhorky, obrovskú porciu roastbeefu (alebo hovädzej šunky) a čerstvú rukolu.","Prikry druhým krajcom, zľahka pritlač dlaňou a prekroj napoly, aby sa ľahko zmestil do krabičky."],t:["mealprep","rychle","studene"]},
{id:"ck83",n:"Studený tuniakový wrap s vajíčkom",c:"obed",p:98,s:2,k:410,pr:44,ca:36,f:10,tm:18,
ing:["2 konzervy tuniaka vo vlastnej šťave (čisté mäso 260 g)","2 veľké celozrnné tortilly","2 vajcia","2 PL bieleho jogurtu alebo ľahkej majonézy","hrsť ľadového šalátu a 1 cibuľa","soľ, čierne korenie"],
st:["Vajcia uvar natvrdo (8 minút), schlaď v studenej vode, ošúp a nakrájaj na plátky.","Odkvapkaného tuniaka zmiešaj v miske s jogurtom, nasekanou cibuľou, soľou a korením.","Tortillu rozlož (bez ohrievania). Do stredu daj šalát, tuniakovú zmes a plátky vajíčka.","Pevne zabaľ z oboch strán, aby nevypadla plnka, prekroj na polovicu a ulož do krabičky."],t:["mealprep","rychle","studene"]},
{id:"ck84",n:"Šalát s kuracím mäsom a quinoou",c:"obed",p:99,s:2,k:495,pr:48,ca:42,f:15,tm:25,
ing:["350 g kuracích pŕs","120 g quinoy (v surovom stave)","1 zrelé avokádo","veľká hrsť mixu listových šalátov","1 PL olivového oleja a citrónová šťava","soľ, grilovacie korenie"],
st:["Quinou prepláchni a uvar v osolenej vode. Nechaj úplne vychladnúť.","Kuracie prsia nakrájaj na pásiky, okoreň a opeč na panvici s olejom. Taktiež nechaj vychladnúť.","Avokádo ošúp a nakrájaj na väčšie kocky. Pokvapkaj ho citrónom, aby nezhnedlo.","V krabičke zmiešaj listový šalát, vychladnutú quinou, kuracie mäso a avokádo."],t:["mealprep","studene"]},
{id:"ck85",n:"Ázijský hovädzí šalát s rezancami",c:"obed",p:100,s:2,k:542,pr:36,ca:50,f:22,tm:20,
ing:["300 g chudého hovädzieho mäsa (steaku)","120 g tenkých ryžových rezancov","30 g nesolených arašidov","1 mrkva a hrsť čerstvého koriandra","2 PL sójovej omáčky a 1 PL sezamového oleja","soľ a chilli"],
st:["Ryžové rezance zalej vriacou vodou, nechaj zmäknúť, zlej a prepláchni ľadovou vodou.","Hovädzí steak zľahka osoľ a opeč na panvici (cca 3 minúty z každej strany). Nechaj 5 minút odpočívať a nakrájaj na tenulinké plátky.","Mrkvu nakrájaj škrabkou na tenké pásiky. Arašidy nasekaj nahrubo.","Zmiešaj studené rezance, mrkvu, mäso a zalej to sójovou omáčkou so sezamovým olejom. Posyp arašidmi a koriandrom."],t:["mealprep","rychle","studene","pikantne"]},
{id:"ck86",n:"Fitness zemiakový šalát s morčacím",c:"obed",p:101,s:2,k:465,pr:58,ca:47,f:5,tm:25,
ing:["400 g morčacích pŕs","500 g zemiakov","150 g bieleho gréckeho jogurtu","1 PL plnotučnej horčice a 2 kyslé uhorky","2 vajcia","soľ, čierne korenie"],
st:["Zemiaky uvar v šupke, nechaj vychladnúť, ošúp a nakrájaj na kocky. Vajcia uvar natvrdo a nakrájaj na kocky.","Morčacie prsia uvar vo vode alebo nasucho upeč, po vychladnutí ich nakrájaj na malé kocky.","V miske vymiešaj jogurt s horčicou, nadrobno nasekanými uhorkami, soľou a korením.","Všetko zľahka premiešaj, aby sa zemiaky úplne nerozpadli, a naporcuj do krabičiek."],t:["mealprep","studene"]},
{id:"ck87",n:"Studený bulgurový šalát s kuracím a Fetou",c:"obed",p:102,s:2,k:476,pr:47,ca:45,f:12,tm:25,
ing:["300 g kuracích pŕs","120 g bulguru (v surovom stave)","80 g syra Feta","1/2 šalátovej uhorky a 150 g cherry paradajok","1 PL olivového oleja a citrónová šťava","soľ, čierne korenie"],
st:["Bulgur zalej vriacou vodou (pomer 1:2), prikry a nechaj napučať 15 minút. Potom ho nechaj vychladnúť.","Kuracie prsia nakrájaj, okoreň, opeč na oleji a nechaj vychladnúť.","Uhorku a paradajky nakrájaj na drobné kúsky.","Všetko zmiešaj dokopy, pokvapkaj citrónovou šťavou, dochuť soľou a navrch rozmrv syr Feta."],t:["mealprep","studene"]},
{id:"ck88",n:"Plnená bageta s trhaným kuracím",c:"obed",p:103,s:2,k:561,pr:60,ca:60,f:9,tm:30,
ing:["400 g kuracích pŕs","2 francúzske celozrnné bagety (spolu cca 200 g)","4 PL kvalitnej BBQ omáčky","60 g syra eidam alebo čedar (plátky)","hrsť čerstvého šalátu","soľ"],
st:["Kuracie prsia vlož do vriacej osolenej vody a var asi 15 minút, kým nie sú úplne mäkké.","Mäso vyber, nechaj mierne vychladnúť a dvoma vidličkami ho natrhaj na jemné vlákna.","Trhané mäso zmiešaj v miske s BBQ omáčkou.","Bagety prekroj, ulož do nich list šalátu, plátky syra, veľkú porciu BBQ trhaného mäsa a zabaľ."],t:["mealprep","studene"]},
{id:"ck89",n:"Grécky šalát s cícerom a panenkou",c:"obed",p:104,s:2,k:409,pr:44,ca:20,f:17,tm:25,
ing:["300 g bravčovej panenky","1 konzerva cíceru (čistá váha cca 240 g)","50 g syra Feta","1 uhorka, 1 paprika, hrsť olív","1 PL olivového oleja","ocot, soľ, oregano"],
st:["Panenku v celku osoľ, okoreň a upeč na panvici (15 minút). Nechaj ju úplne vychladnúť a nakrájaj na tenké medailóniky.","Cícer dôkladne prepláchni pod studenou vodou.","Zeleninu nakrájaj na hrubšie kocky. Zmiešaj ju s cícerom, olivami, olejom, kvapkou octu a oreganom.","Do krabičiek nalož zeleninovo-cícerovú zmes, navrch ulož medailóniky studenej panenky a kúsky Fety."],t:["mealprep","studene"]},
{id:"ck90",n:"Lososový sendvič s vajíčkom a krémovým syrom",c:"obed",p:105,s:2,k:472,pr:33,ca:40,f:20,tm:18,
ing:["200 g údeného lososa (na tenké plátky)","4 krajce tmavého ražného chleba (spolu cca 200 g)","2 vajcia","50 g krémového syra (typu Lučina alebo žervé)","hrsť rukoly alebo poľníčka","citrónová šťava, čierne korenie"],
st:["Vajcia uvar natvrdo (8 minút), ošúp a nakrájaj na tenké kolieska.","Všetky krajce ražného chleba natri hrubšou vrstvou krémového syra.","Na syr ulož plátky údeného lososa, zľahka ho pokvapkaj citrónom a okoreň.","Pridaj kolieska vajíčok, hrsť rukoly, priklop druhým chlebom, zľahka zatlač a prekroj napoly."],t:["mealprep","rychle","studene"]},

{id:"ck91",n:"Tuniak s kuskusom a kukuricou",c:"obed",p:107,s:2,k:461,pr:45,ca:50,f:9,tm:10,
ing:["2 konzervy tuniaka vo vlastnej šťave (čisté mäso 260 g)","100 g kuskusu (v surovom stave)","100 g kukurice z konzervy","100 g bieleho gréckeho jogurtu","1 PL olivového oleja","soľ, čierne korenie"],
st:["Kuskus nasyp do misky, pokvapkaj polovicou olivového oleja, osoľ a zalej vriacou vodou tesne nad jeho povrch. Prikry na 5 minút.","Tuniaka zlej zo šťavy a v miske ho rozmiešaj s gréckym jogurtom a kukuricou.","Kuskus prekypri vidličkou, pridaj k nemu tuniakovú zmes a poriadne premiešaj.","Dochuť čiernym korením a rozdeľ do dvoch krabičiek. Jedlo je skvelé teplé aj studené."],t:["mealprep","mikrovlnka","rychle","studene"]},
{id:"ck92",n:"Mexické hovädzie s ryžou",c:"obed",p:108,s:2,k:690,pr:50,ca:73,f:22,tm:20,
ing:["300 g chudého mletého hovädzieho mäsa","120 g ryže (v surovom stave)","200 g červenej fazule (z konzervy, prepláchnutej)","200 g paradajkového pretlaku alebo salsy","40 g syra čedar (nastrúhaného)","1 PL olivového oleja, soľ a chilli"],
st:["Ryžu daj uvariť podľa návodu v osolenej vode.","Na panvici rozpáľ olej a mleté mäso opekaj, kým nezhnedne a nevypustí šťavu. Osoľ a pridaj chilli.","Pridaj fazuľu a paradajkovú salsu. Prehrej na panvici asi 5 minút, nech to zhustne.","Do krabičiek nalož ryžu, pridaj mexické hovädzie a navrch posyp čedarom (pri ohrievaní sa roztopí)."],t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"ck93",n:"Kuracie gnocchi s pestom",c:"obed",p:109,s:2,k:637,pr:57,ca:55,f:21,tm:15,
ing:["400 g kuracích pŕs","300 g zemiakových gnocchi","50 g bazalkového pesta","150 g cherry paradajok","50 g mozzarelly","soľ, čierne korenie"],
st:["Gnocchi hoď do vriacej osolenej vody a var, kým nevyplávajú na povrch (cca 2–3 minúty).","Kuracie prsia nakrájaj na kocky a opeč nasucho (alebo na kvapke oleja) na panvici dozlatista. Osoľ a okoreň.","Ku kuraciemu mäsu pridaj prekrojené cherry paradajky, uvarené gnocchi a bazalkové pesto.","Dôkladne premiešaj a rozdeľ do krabičiek. Navrch natrhaj kúsky mozzarelly."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck94",n:"Morčacie na sladkej chilli omáčke",c:"obed",p:110,s:2,k:635,pr:60,ca:65,f:15,tm:20,
ing:["400 g morčacích pŕs","120 g ryže (v surovom stave)","300 g brokolice","40 g sladkej chilli omáčky (Sweet Chili)","20 g nesolených arašidov (nasekaných)","1 PL olivového oleja a soľ"],
st:["Ryžu uvar klasicky. Brokolicu rozober na ružičky a 5 minút povar vo vriacej vode.","Morčacie mäso nakrájaj na kocky, osoľ a sprudka opeč na oleji na panvici dozlatista.","K mäsu pridaj sladkú chilli omáčku, minútu prehrej, aby obalila každý kúsok mäsa.","Do krabičiek rozdeľ ryžu, brokolicu a lepivé morčacie mäso. Posyp nasekanými arašidmi."],t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"ck95",n:"Krémové cestoviny so šunkou a syrom",c:"obed",p:111,s:2,k:601,pr:44,ca:68,f:17,tm:20,
ing:["150 g cestovín (penne)","200 g kvalitnej chudej šunky","100 g syra eidam alebo gouda (nastrúhaného)","100 g kukurice z konzervy","100 ml smotany na varenie (12%)","soľ, čierne korenie"],
st:["Cestoviny uvar al dente v osolenej vode.","Na hlbšej panvici nasucho jemne opeč na kocky nakrájanú šunku a kukuricu.","Zalej to smotanou, nechaj zohriať, odstav z ohňa a okamžite primiešaj nastrúhaný syr. Miešaj, kým nevznikne hladká omáčka.","Prisyp uvarené cestoviny, dôkladne premiešaj, okoreň čiernym korením a zabaľ."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck96",n:"Zapekané kura s kyslou kapustou",c:"obed",p:112,s:2,k:540,pr:52,ca:38,f:20,tm:40,
ing:["400 g kuracích pŕs","400 g zemiakov","200 g kvasenej kapusty (vyžmýkanej)","50 g oravskej slaniny (na kocky)","1 PL olivového oleja","soľ, rasca a mletá paprika"],
st:["Rúru predhrej na 200 °C. Zemiaky nakrájaj na hranolky, kuracie mäso na väčšie kocky.","Kvasenú kapustu rozlož na plech. Pridaj zemiaky a kuracie mäso.","Všetko pokvapkaj olejom, osoľ, bohato posyp rascou, paprikou a pridaj kocky slaniny. Premiešaj rukami.","Peč v rúre cca 30 minút, kým mäso nie je hotové a slanina chrumkavá. Rozdeľ do krabičiek."],t:["mealprep","mikrovlnka"]},
{id:"ck97",n:"Kuracia quesadilla s paradajkovou salsou",c:"obed",p:113,s:2,k:540,pr:51,ca:39,f:20,tm:15,
ing:["300 g kuracích pŕs","2 veľké celozrnné tortilly","80 g tvrdého syra (gouda alebo čedar)","100 g hustej paradajkovej salsy (z pohára)","1 PL olivového oleja","soľ a mexické korenie"],
st:["Kuracie prsia nasekaj na úplne malé kúsky. Osoľ, okoreň a sprudka opeč na oleji.","Na polovicu každej tortilly natri paradajkovú salsu, ulož mäso a zasyp nastrúhaným syrom.","Tortillu prelož napoly a nasucho ju na panvici z oboch strán opeč, kým nebude chrumkavá a syr roztavený.","Nechaj 2 minúty vychladnúť, rozkroj na trojuholníky a ulož do krabičiek."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck98",n:"Ázijský losos s hráškom a ryžou",c:"obed",p:114,s:2,k:683,pr:51,ca:59,f:27,tm:20,
ing:["400 g lososového filetu (2 kusy)","120 g ryže (v surovom stave)","200 g mrazeného hrášku","2 PL tmavej sójovej omáčky","1 ČL medu (voliteľné)","soľ (len na ryžu)"],
st:["Ryžu uvar vo vode. Hrášok len zalej vriacou vodou, nechaj 3 minúty stáť a zlej.","Lososa potri zmesou sójovej omáčky (a medu).","Na panvici nasucho (losos má dosť tuku) alebo na papieri na pečenie v rúre (200 °C na 12 minút) lososa upeč.","Krabičku naplň ryžou zmiešanou s hráškom a na to ulož ázijského lososa."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck99",n:"Arašidové rezance s mletým mäsom",c:"obed",p:115,s:2,k:629,pr:46,ca:64,f:21,tm:17,
ing:["300 g chudého mletého mäsa (bravčové alebo morčacie)","150 g rezancov (soba, ryžové alebo klasické špagety)","200 g mrazenej ázijskej zeleniny","30 g 100% arašidového masla","3 PL sójovej omáčky a 1 PL oleja"],
st:["Rezance uvar podľa návodu. V miske rozmiešaj arašidové maslo, sójovú omáčku a 3 lyžice horúcej vody na hladkú omáčku.","Na oleji orestuj mleté mäso, kým nie je prepečené.","Pridaj mrazenú zeleninu a restuj ďalšie 4 minúty do zmäknutia.","Pridaj rezance, zalej arašidovou omáčkou, poriadne na panvici premiešaj a po minúte zabaľ."],t:["mealprep","mikrovlnka","rychle"]},
{id:"ck100",n:"Zapekané proteínové vločky (Sladká odmena)",c:"dezert",p:116,s:2,k:558,pr:49,ca:50,f:18,tm:30,
ing:["100 g ovsených vločiek","400 g (2 tégliky) Cottage cheese","2 vajcia","1 odmerka proteínu (30 g, ideálne čokoláda)","200 g mrazeného lesného ovocia (alebo čučoriedok)","štipka prášku do pečiva a škorica"],
st:["Rúru predhrej na 180 °C. Do veľkej misky daj vločky, proteín, škoricu a prášok do pečiva.","Pridaj vajcia a Cottage cheese. Poriadne všetko vymiešaj na husté cesto.","Cesto vylej do malej zapekacej misy (alebo priamo do dvoch sklenených krabičiek vhodných do rúry). Navrch nasyp mrazené ovocie a zľahka ho zatlač do cesta.","Peč asi 25 minút, kým okraje nie sú chrumkavé."],t:["mealprep","mikrovlnka","bezmasa"]}
];
